// The serverless functions in api/ cannot import from src/ once deployed, so the two things they share with the app
// (the blocklist and the list of feed addresses) are copied into api/_*.ts before every build. Do not edit the copies.
import { readFileSync, writeFileSync } from 'node:fs'
const note = '// Generated by scripts/sync-api.mjs from src/lib; edit the original, not this copy.\n'
writeFileSync('api/_blocklist.ts', note + readFileSync('src/lib/blocklist.ts', 'utf8'))
const feeds = readFileSync('src/lib/feeds.ts', 'utf8')
const urls = [...feeds.matchAll(/\['\w+', "[^"]+", '([^']+)', (?:true|false)\]/g)].map((m) => m[1])
writeFileSync('api/_feeds.ts', `${note}export const FEED_URLS: string[] = ${JSON.stringify(urls, null, 1)}\n`)
console.log(`api/_blocklist.ts and api/_feeds.ts written (${urls.length} feeds)`)
